-- MAGIC %md-sandbox
-- MAGIC #### B2.2 Configure Permissions and Ownerships
-- MAGIC
-- MAGIC In a SQL editor or notebook, execute the following SQL code to configure permissions on the catalogs, recalling that:
-- MAGIC - the engineering team has "all" access for the development and staging catalogs
-- MAGIC - read-only for the production catalog
-- MAGIC
-- MAGIC <div class="code-block" data-language="sql">
-- MAGIC GRANT USE CATALOG,BROWSE,CREATE SCHEMA ON CATALOG eng_dev TO `engg`;
-- MAGIC GRANT USE CATALOG,BROWSE,CREATE SCHEMA ON CATALOG eng_stg TO `engg`;
-- MAGIC GRANT USE CATALOG,BROWSE ON CATALOG eng_prd TO `engg`;
-- MAGIC </div>
-- MAGIC
